refused_program.body:
git fetch {upstream_remote} {upstream_branch}
git merge --no-commit --no-ff {upstream_remote}/{upstream_branch} || true
tmp=$(mktemp -d)
for f in $(git diff --name-only --diff-filter=U); do
  git show :1:"$f" > "$tmp/base" 2>/dev/null || true
  git show :2:"$f" > "$tmp/ours" 2>/dev/null || true
  git show :3:"$f" > "$tmp/up" 2>/dev/null || true
  git diff --no-color -U0 --no-index "$tmp/base" "$tmp/ours" 2>/dev/null | awk '
    function flush() {
      k = (nm < np) ? nm : np
      for (i = k + 1; i <= np; i++) print pm[i]
      nm = 0
      np = 0
    }
    /^---/ { next }
    /^\+\+\+/ { next }
    /^@@/ { flush(); next }
    /^-/ { nm++; next }
    /^\+/ { pm[++np] = substr($0, 2); next }
    END { flush() }
  ' > "$tmp/added"
  awk -v up="$tmp/up" '
    BEGIN {
      while ((getline l < up) > 0) {
        if (!(l in seen)) { seen[l] = 1; content[++m] = l }
      }
      close(up)
    }
    FNR == NR {
      if (length($0) > 0) { add[$0] = 1 }
      next
    }
    {
      if ($0 in add) {
        if (!($0 in seen)) { j = ++pc[anchor]; pl[anchor, j] = $0 }
      } else if ($0 in seen) {
        anchor = $0
      }
    }
    END {
      for (i = 1; i <= m; i++) {
        l = content[i]
        print l
        if ((l in pc) && !(l in done)) {
          for (j = 1; j <= pc[l]; j++) print pl[l, j]
          done[l] = 1
        }
      }
      for (a in pc) {
        if (!(a in done)) {
          for (j = 1; j <= pc[a]; j++) print pl[a, j]
          done[a] = 1
        }
      }
    }
  ' "$tmp/added" "$tmp/ours" > "$f"
done
git add -A
git commit --no-edit
rm -rf "$tmp"
